# box::use(dplyr[mutate]) in the project .Rprofile (runs in every R process)
# Generated by ../../04-targets.R. Run here: Rscript -e 'targets::tar_make()'  (USE_CREW=true for crew)
library(targets)
if (Sys.getenv("USE_CREW") == "true")
  tar_option_set(controller = crew::crew_controller_local(name = "crew", workers = 2, seconds_idle = 10))
tar_option_set(error = "continue")   # every target reports its own outcome

add_x <- function(d) mutate(d, x = var1 * 2)

list(
  tar_target(raw, data.frame(var1 = 1:3)),
  tar_target(out, add_x(raw)),
  tar_target(ran_on, Sys.getenv("CREW_CONTROLLER", "main process"))
)
